package com.peiwan.platform.order;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.peiwan.platform.payment.OrderPaymentService;import com.peiwan.platform.settlement.SettlementService;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class OrderService{
 private final OrderMapper orders;private final OrderItemMapper items;private final OrderGameProfileMapper profiles;private final OrderStatusLogMapper logs;private final OrderDataMapper data;private final PlayerMapper players;private final ObjectMapper json;private final OrderPaymentService paymentService;private final SettlementService settlementService;private final CustomerGameProfileMapper customerProfiles;private final GameServerMapper gameServers;private final GameRankMapper gameRanks;private final GameRankSystemMapper rankSystems;private final OrderMemberService orderMembers;
 public OrderService(OrderMapper orders,OrderItemMapper items,OrderGameProfileMapper profiles,OrderStatusLogMapper logs,OrderDataMapper data,PlayerMapper players,ObjectMapper json,OrderPaymentService paymentService,SettlementService settlementService,CustomerGameProfileMapper customerProfiles,GameServerMapper gameServers,GameRankMapper gameRanks,GameRankSystemMapper rankSystems,OrderMemberService orderMembers){this.orders=orders;this.items=items;this.profiles=profiles;this.logs=logs;this.data=data;this.players=players;this.json=json;this.paymentService=paymentService;this.settlementService=settlementService;this.customerProfiles=customerProfiles;this.gameServers=gameServers;this.gameRanks=gameRanks;this.rankSystems=rankSystems;this.orderMembers=orderMembers;}
 public Map<String,Object> list(int current,int size,String orderNo,String customerName,String status){current=Math.max(1,current);size=Math.min(200,Math.max(1,size));var result=data.orders(new Page<>(current,size),s(orderNo),s(customerName),status);return Map.of("records",result.getRecords().stream().map(this::orderView).toList(),"current",current,"size",size,"total",result.getTotal());}
 public Map<String,Object> detail(long id){var row=data.orderDetail(id);if(row==null)throw new IllegalArgumentException("订单不存在");var order=orderView(row);order.put("members",orderMembers.members(id).stream().map(this::memberView).toList());order.put("items",items.selectList(new QueryWrapper<OrderItemEntity>().eq("order_id",id).orderByAsc("id")).stream().map(this::itemView).toList());var profile=profiles.selectOne(new QueryWrapper<OrderGameProfileEntity>().eq("order_id",id));order.put("gameProfile",profile==null?null:profileView(profile));order.put("statusLogs",data.statusLogs(id).stream().map(this::logView).toList());return order;}
 public List<Map<String,Object>> customers(){return data.customers().stream().map(r->map("id",r.get("id"),"label",Objects.toString(r.get("nickname"),Objects.toString(r.get("username"))),"username",r.get("username"),"phone",r.get("phone"))).toList();}
 public List<Map<String,Object>> players(){return data.players().stream().map(r->map("id",r.get("id"),"label",r.get("nickname"),"playerNo",r.get("player_no"))).toList();}
 @Transactional public long create(CreateCommand c,long operator){if(c.customerId()==null)throw new IllegalArgumentException("请选择下单用户");if(c.skuId()==null)throw new IllegalArgumentException("请选择销售规格");if(c.quantity()<1)throw new IllegalArgumentException("购买数量必须大于0");var customer=data.enabledCustomer(c.customerId());if(customer==null)throw new IllegalArgumentException("下单用户不存在或已禁用");var sku=data.skuSnapshot(c.skuId());if(sku==null)throw new IllegalArgumentException("销售规格不存在");if(!"ON_SALE".equals(sku.get("product_status"))||!Boolean.TRUE.equals(sku.get("enabled")))throw new IllegalArgumentException("商品或销售规格未上架");int min=((Number)sku.get("min_quantity")).intValue();Integer max=sku.get("max_quantity")==null?null:((Number)sku.get("max_quantity")).intValue();if(c.quantity()<min||max!=null&&c.quantity()>max)throw new IllegalArgumentException("购买数量不符合规格限制");var pricing=resolvePrice(c,sku);if("LIMITED".equals(sku.get("stock_mode"))&&data.decrementStock(c.skuId(),c.quantity())==0)throw new IllegalArgumentException("库存不足");var unit=(BigDecimal)pricing.get("price");int playerCount=sku.get("player_count")==null?1:((Number)sku.get("player_count")).intValue();String priceType=Objects.toString(sku.get("price_type"),"PER_PLAYER");var total=unit.multiply(BigDecimal.valueOf(c.quantity()));if("PER_PLAYER".equals(priceType))total=total.multiply(BigDecimal.valueOf(playerCount));var o=new OrderEntity();o.orderNo=orderNo();o.customerId=c.customerId();o.requestedPlayerId=c.requestedPlayerId();o.requestedPlayerLevelId=(Long)pricing.get("levelId");o.playerLevelCode=(String)pricing.get("levelCode");o.playerLevelName=(String)pricing.get("levelName");o.pricingMode=(String)sku.get("pricing_mode");o.requiredPlayerCount=playerCount;o.skuPriceType=priceType;o.baseUnitPrice=unit;o.orderStatus="PENDING_PAYMENT";o.totalAmount=total;o.payableAmount=total;o.paidAmount=BigDecimal.ZERO;o.contactName=blank(c.contactName(),Objects.toString(customer.get("nickname"),Objects.toString(customer.get("username"))));o.contactPhone=blank(c.contactPhone(),Objects.toString(customer.get("phone"),""));o.customerRemark=c.customerRemark();o.createdBy=operator;orders.insert(o);var item=new OrderItemEntity();item.orderId=o.id;item.productId=((Number)sku.get("product_id")).longValue();item.skuId=c.skuId();item.pricingRuleId=(Long)pricing.get("ruleId");item.productCode=(String)sku.get("product_code");item.productName=(String)sku.get("product_name");item.skuCode=(String)sku.get("sku_code");item.skuName=(String)sku.get("sku_name");item.productType=(String)sku.get("product_type");item.unitPrice=unit;item.quantity=c.quantity();item.subtotalAmount=total;item.serviceSnapshot=serviceSnapshot(item.productId);items.insert(item);var profile=gameProfile(c,sku,o.id);profiles.insert(profile);log(o.id,null,"PENDING_PAYMENT",operator,"创建订单");return o.id;}
 private OrderGameProfileEntity gameProfile(CreateCommand c,Map<String,Object> sku,long orderId){long gameId=((Number)sku.get("game_id")).longValue();CustomerGameProfileEntity saved=null;if(c.customerGameProfileId()!=null){saved=customerProfiles.selectOne(new QueryWrapper<CustomerGameProfileEntity>().eq("id",c.customerGameProfileId()).eq("user_id",c.customerId()).eq("enabled",true));if(saved==null||!Objects.equals(saved.gameId,gameId))throw new IllegalArgumentException("所选游戏账号与商品不匹配");}Long serverId=c.serverId()!=null?c.serverId():saved==null?null:saved.serverId;var server=serverId==null?null:gameServers.selectById(serverId);if(serverId!=null&&(server==null||!Objects.equals(server.gameId,gameId)))throw new IllegalArgumentException("区服与商品所属游戏不一致");var current=c.currentRankId()==null?null:gameRanks.selectById(c.currentRankId());var target=c.targetRankId()==null?null:gameRanks.selectById(c.targetRankId());if(c.currentRankId()!=null&&(current==null||!rankBelongsToGame(current,gameId))||c.targetRankId()!=null&&(target==null||!rankBelongsToGame(target,gameId)))throw new IllegalArgumentException("段位与商品所属游戏不一致");var profile=new OrderGameProfileEntity();profile.orderId=orderId;profile.gameId=gameId;profile.customerGameProfileId=saved==null?null:saved.id;profile.serverId=serverId;profile.currentRankId=current==null?null:current.id;profile.targetRankId=target==null?null:target.id;profile.gameName=(String)sku.get("game_name");profile.gameAccount=saved==null?c.gameAccount():saved.gameAccount;profile.gameNickname=saved==null?c.gameNickname():saved.gameNickname;profile.serverName=server==null?c.serverName():server.serverName;profile.currentRankName=current==null?c.rankName():current.rankName;profile.targetRankName=target==null?null:target.rankName;profile.rankName=profile.currentRankName;profile.extraRequirement=c.extraRequirement();return profile;}
 private boolean rankBelongsToGame(GameRankEntity rank,long gameId){var system=rankSystems.selectById(rank.rankSystemId);return system!=null&&Objects.equals(system.gameId,gameId);}
 private Map<String,Object> resolvePrice(CreateCommand c,Map<String,Object> sku){var result=new HashMap<String,Object>();result.put("price",sku.get("price"));if(!"SERVICE".equals(sku.get("product_type")))return result;Long levelId=c.playerLevelId();if(c.requestedPlayerId()!=null){var playerLevel=data.playerGameLevel(c.requestedPlayerId(),((Number)sku.get("game_id")).longValue());if(playerLevel==null)throw new IllegalArgumentException("指定陪玩师未认证当前游戏");levelId=((Number)playerLevel.get("id")).longValue();}if(levelId==null)return result;var level=data.playerLevel(levelId);if(level==null||!Boolean.TRUE.equals(level.get("enabled")))throw new IllegalArgumentException("陪玩等级不存在或已停用");if(!Objects.equals(((Number)level.get("game_id")).longValue(),((Number)sku.get("game_id")).longValue()))throw new IllegalArgumentException("陪玩等级与商品所属游戏不一致");result.put("levelId",levelId);result.put("levelCode",level.get("level_code"));result.put("levelName",level.get("level_name"));var rule=data.levelPrice(c.skuId(),levelId);if(rule!=null&&Boolean.TRUE.equals(rule.get("enabled"))){result.put("price",rule.get("price"));result.put("baseUnitPrice",rule.get("base_unit_price"));result.put("ruleId",((Number)rule.get("id")).longValue());}return result;}
 @Transactional public void changeStatus(long id,String target,String reason,long operator){var o=requireOrder(id);String from=o.orderStatus;var allowed=Map.of("PENDING_PAYMENT",Set.of("CANCELLED"),"WAIT_ASSIGN",Set.of("CANCELLED"),"ASSIGNED",Set.of("IN_SERVICE","CANCELLED"),"IN_SERVICE",Set.of("COMPLETED"));if(!allowed.getOrDefault(from,Set.of()).contains(target))throw new IllegalArgumentException("订单不能从"+from+"变更为"+target);var memberIds=orderMembers.activePlayerIds(id);o.orderStatus=target;o.updatedAt=LocalDateTime.now();if("IN_SERVICE".equals(target)){o.serviceStartedAt=LocalDateTime.now();orderMembers.updateStatuses(id,"IN_SERVICE");}else if("COMPLETED".equals(target)){o.completedAt=LocalDateTime.now();orderMembers.updateStatuses(id,"COMPLETED");}else{paymentService.refundOrder(id,operator,reason);o.paidAmount=BigDecimal.ZERO;o.cancelReason=reason;o.cancelledAt=LocalDateTime.now();orderMembers.updateStatuses(id,"CANCELLED");restoreStock(id);}orders.updateById(o);if("COMPLETED".equals(target))settlementService.settleOrder(id);if("COMPLETED".equals(target)||"CANCELLED".equals(target))for(var playerId:memberIds)if(data.activePlayerOrders(playerId)==0){var p=players.selectById(playerId);if(p!=null){p.workStatus="AVAILABLE";p.updatedAt=LocalDateTime.now();players.updateById(p);}}log(id,from,target,operator,reason);}
 @Transactional public void cancelOwn(long uid,long id,String reason){var o=orders.selectOne(new QueryWrapper<OrderEntity>().eq("id",id).eq("customer_id",uid));if(o==null)throw new IllegalArgumentException("订单不存在或不属于当前用户");if(!Set.of("PENDING_PAYMENT","WAIT_ASSIGN").contains(o.orderStatus))throw new IllegalArgumentException("当前订单不能取消");changeStatus(id,"CANCELLED",reason,uid);}
 @Transactional public void assign(long id,long playerId,String reason,long operator){var o=requireOrder(id);if(!"WAIT_ASSIGN".equals(o.orderStatus))throw new IllegalArgumentException("只有待派单订单可以分配陪玩师");var p=players.selectById(playerId);if(p==null||!Boolean.TRUE.equals(p.enabled)||!"APPROVED".equals(p.auditStatus))throw new IllegalArgumentException("陪玩师不存在、未启用或未通过审核");var profile=profiles.selectOne(new QueryWrapper<OrderGameProfileEntity>().eq("order_id",id));if(profile!=null&&o.requestedPlayerLevelId!=null&&!data.playerMatchesLevel(playerId,profile.gameId,o.requestedPlayerLevelId))throw new IllegalArgumentException("该陪玩师在当前游戏的等级与订单要求不一致");if(o.requestedPlayerId!=null&&!Objects.equals(o.requestedPlayerId,playerId)&&!orderMembers.belongs(id,o.requestedPlayerId))throw new IllegalArgumentException("订单需要先由指定陪玩师接单");var joined=orderMembers.join(id,playerId,"ADMIN",null);p.workStatus="BUSY";p.updatedAt=LocalDateTime.now();players.updateById(p);if(joined.full())log(id,"WAIT_ASSIGN","ASSIGNED",operator,"成员已满"+joined.memberCount()+"/"+joined.requiredCount()+"人；"+Objects.toString(reason,""));}
 private void restoreStock(long id){for(var r:data.stockRows(id))if("LIMITED".equals(r.get("stock_mode")))data.restoreStock(((Number)r.get("sku_id")).longValue(),((Number)r.get("quantity")).intValue());}
 private String serviceSnapshot(long productId){try{return json.writeValueAsString(data.serviceSnapshot(productId));}catch(JsonProcessingException e){throw new IllegalArgumentException("商品服务快照生成失败");}}
 private void log(long id,String from,String to,long operator,String reason){var l=new OrderStatusLogEntity();l.orderId=id;l.fromStatus=from;l.toStatus=to;l.operatorId=operator;l.reason=reason;logs.insert(l);}
 private OrderEntity requireOrder(long id){var x=orders.selectById(id);if(x==null)throw new IllegalArgumentException("订单不存在");return x;}
 private Map<String,Object> orderView(Map<String,Object>r){return view(r,new String[][]{{"id","id"},{"orderNo","order_no"},{"customerId","customer_id"},{"customerUsername","customer_username"},{"customerNickname","customer_nickname"},{"assignedPlayerId","assigned_player_id"},{"requestedPlayerId","requested_player_id"},{"requestedPlayerLevelId","requested_player_level_id"},{"playerLevelCode","player_level_code"},{"playerLevelName","player_level_name"},{"pricingMode","pricing_mode"},{"requiredPlayerCount","required_player_count"},{"memberCount","member_count"},{"skuPriceType","sku_price_type"},{"baseUnitPrice","base_unit_price"},{"playerName","player_name"},{"productName","product_name"},{"orderStatus","order_status"},{"totalAmount","total_amount"},{"payableAmount","payable_amount"},{"paidAmount","paid_amount"},{"contactName","contact_name"},{"contactPhone","contact_phone"},{"customerRemark","customer_remark"},{"cancelReason","cancel_reason"},{"paidAt","paid_at"},{"assignedAt","assigned_at"},{"serviceStartedAt","service_started_at"},{"completedAt","completed_at"},{"cancelledAt","cancelled_at"},{"createTime","created_at"}});}private Map<String,Object> memberView(Map<String,Object>r){return view(r,new String[][]{{"id","id"},{"playerId","player_id"},{"playerNo","player_no"},{"playerName","player_name"},{"avatarUrl","avatar_url"},{"memberStatus","member_status"},{"joinSource","join_source"},{"dispatchTaskId","dispatch_task_id"},{"joinedAt","joined_at"},{"serviceStartedAt","service_started_at"},{"completedAt","completed_at"},{"cancelledAt","cancelled_at"}});}private Map<String,Object> itemView(OrderItemEntity r){return map("id",r.id,"productId",r.productId,"skuId",r.skuId,"pricingRuleId",r.pricingRuleId,"productCode",r.productCode,"productName",r.productName,"skuCode",r.skuCode,"skuName",r.skuName,"productType",r.productType,"unitPrice",r.unitPrice,"quantity",r.quantity,"subtotalAmount",r.subtotalAmount,"serviceSnapshot",r.serviceSnapshot);}private Map<String,Object> profileView(OrderGameProfileEntity r){return map("gameId",r.gameId,"gameName",r.gameName,"customerGameProfileId",r.customerGameProfileId,"serverId",r.serverId,"currentRankId",r.currentRankId,"targetRankId",r.targetRankId,"gameAccount",r.gameAccount,"gameNickname",r.gameNickname,"serverName",r.serverName,"rankName",r.rankName,"currentRankName",r.currentRankName,"targetRankName",r.targetRankName,"extraRequirement",r.extraRequirement);}private Map<String,Object> logView(Map<String,Object>r){return view(r,new String[][]{{"id","id"},{"fromStatus","from_status"},{"toStatus","to_status"},{"operatorId","operator_id"},{"operatorName","operator_name"},{"reason","reason"},{"createTime","created_at"}});}private Map<String,Object> view(Map<String,Object>r,String[][]keys){var out=new LinkedHashMap<String,Object>();for(var k:keys)if(r.containsKey(k[1]))out.put(k[0],r.get(k[1]));return out;}
 private Map<String,Object> map(Object...v){var m=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)if(v[i+1]!=null)m.put((String)v[i],v[i+1]);return m;}private String orderNo(){return "ORD"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();}private String s(String v){return Objects.toString(v,"");}private String blank(String v,String d){return v==null||v.isBlank()?d:v;}public record CreateCommand(Long customerId,Long skuId,int quantity,String contactName,String contactPhone,String customerRemark,String gameAccount,String gameNickname,String serverName,String rankName,String extraRequirement,Long requestedPlayerId,Long playerLevelId,Long customerGameProfileId,Long serverId,Long currentRankId,Long targetRankId){}
}
